package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import android.content.*;import android.view.*;import android.widget.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,packageName="de.mika.promptwerk")
public class HandoverTests {
 MainActivity a;
 @Before public void start(){RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void stop(){a.onDestroy();}
 Button find(View v,String s){if(v instanceof Button&&s.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),s);if(b!=null)return b;}return null;}
 @Test public void transferCopiesLocksRestoresAndNewPromptSupportsUndo(){a.editor.setText("Fertiger Prompt");a.handover();assertTrue(a.handedOver);assertFalse(a.editor.isEnabled());assertEquals("Fertiger Prompt",((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip().getItemAt(0).getText().toString());MainActivity cold=Robolectric.buildActivity(MainActivity.class).setup().get();assertTrue(cold.handedOver);assertFalse(cold.editor.isEnabled());assertEquals("Fertiger Prompt",cold.editor.getText().toString());cold.onDestroy();a.newPrompt();assertTrue(a.editor.isEnabled());assertEquals("",a.editor.getText().toString());a.undo();assertEquals("Fertiger Prompt",a.editor.getText().toString());}
 @Test public void insertStartsFreshAndDoesNotCombineHandedOverFiles()throws Exception{a.editor.setText("Erledigt");a.draftFiles.add(new MainActivity.Att(String.join("",java.util.Collections.nCopies(64,"a")),"Alt.txt","text/plain",3));a.handover();MainActivity.Item item=new MainActivity.Item("Neu","Neuer Text","prompt");a.insertItem(item);assertEquals("Neuer Text",a.editor.getText().toString());assertTrue(a.draftFiles.isEmpty());assertFalse(a.handedOver);}
 @Test public void lockedFullscreenCannotEnableWritingUntilResume(){a.editor.setText("Fertig");a.expandEditor();a.setReading(true);a.handover();a.setReading(false);assertFalse(a.editor.isEnabled());find(a.expandedDialog.getWindow().getDecorView(),"Weiterbearbeiten").performClick();assertTrue(a.editor.isEnabled());assertNotNull(a.editor.getKeyListener());a.expandedDialog.dismiss();assertTrue(a.editor.isEnabled());}
 @Test public void directCopyWorksForActiveAndCompletedEntriesWithoutTouchingDraft(){a.editor.setText("Mein Entwurf");MainActivity.Item item=a.items.stream().filter(i->i.type.equals("prompt")).findFirst().get();find(a.rows,"Kopieren").performClick();assertEquals(item.text,((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip().getItemAt(0).getText().toString());assertEquals("Mein Entwurf",a.editor.getText().toString());find(a.rows,"Erledigt").performClick();a.showOverview();assertNotNull(a.overviewDialog);assertNull(find(a.overviewRows,"Kopieren"));assertNull(find(a.overviewRows,"Zurückholen"));a.copyText(item.title,item.text);assertEquals(item.text,((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip().getItemAt(0).getText().toString());}
 @Test public void emptyTransferDoesNotLock(){a.handover();assertFalse(a.handedOver);assertTrue(a.editor.isEnabled());}
 @Test public void updateParserRejectsWrongPackageAndForeignOrMalformedUrls()throws Exception{String json="{\"packageName\":\"de.mika.promptwerk\",\"versionCode\":12,\"versionName\":\"2.7\",\"apkUrl\":\"https://gsgev.org/apps/Promptwerk-2.7.apk\"}";assertEquals(12,UpdateInfo.parse(json).code);for(String bad:new String[]{json.replace("de.mika.promptwerk","other.app"),json.replace("https:","http:"),json.replace("gsgev.org","evil.example"),json.replace("2.7.apk","../2.7.apk"),json.replace("2.7.apk","2.7.apk?x=1")})try{UpdateInfo.parse(bad);fail(bad);}catch(java.io.IOException expected){}}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void previewAndImprintOrder()throws Exception{
 View content=a.findViewById(android.R.id.content);content.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(800,1073741824));content.layout(0,0,360,800);shot(content,"tests/Promptwerk-2.7-Hauptbildschirm.png",360,800);
 assertEquals(a.dp(36),a.root.getChildAt(0).getHeight());a.showInfo();LinearLayout body=(LinearLayout)((ScrollView)((ViewGroup)a.fox.getParent()).getParent().getParent()).getChildAt(0);int textIndex=-1,foxIndex=body.indexOfChild((View)a.fox.getParent());for(int i=0;i<body.getChildCount();i++){View child=body.getChildAt(i);if(child instanceof TextView&&((TextView)child).getText().toString().contains("Amtsgericht"))textIndex=i;}assertTrue(textIndex>=0);assertTrue(foxIndex>textIndex);View decor=a.infoDialog.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(760,1073741824));decor.layout(0,0,360,760);shot(decor,"tests/Promptwerk-2.7-Impressum.png",360,760);a.infoDialog.dismiss();a.showDraft();a.editor.setText("Dieser Prompt wurde bereits übergeben.");a.handover();content.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(800,1073741824));content.layout(0,0,360,800);shot(content,"tests/Promptwerk-2.7-Uebergeben.png",360,800);
 }
 void shot(View v,String path,int w,int h)throws Exception{android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.OutputStream out=new java.io.FileOutputStream(path)){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
}
